import logging
from collections.abc import Callable

import pytest


def wrapped(job: Callable[[], str]) -> str:
    """Call job once and return "start:" + its result + ":end".

    The helper itself uses no capabilities: it does no printing, logging,
    or I/O. Anything the job does is the caller's business. Exceptions
    raised by the job propagate unchanged.
    """
    return "start:" + job() + ":end"


def test_wraps_result() -> None:
    assert wrapped(lambda: "x") == "start:x:end"


def test_empty_result() -> None:
    assert wrapped(lambda: "") == "start::end"


def test_result_containing_markers_is_not_altered() -> None:
    assert wrapped(lambda: "start:end:") == "start:start:end::end"


def test_multiline_and_unicode_result() -> None:
    assert wrapped(lambda: "a\nb é") == "start:a\nb é:end"


def test_job_called_exactly_once() -> None:
    calls: list[int] = []

    def job() -> str:
        calls.append(1)
        return "r"

    assert wrapped(job) == "start:r:end"
    assert len(calls) == 1


def test_job_may_use_caller_state() -> None:
    state = {"n": 0}

    def job() -> str:
        state["n"] += 1
        return str(state["n"])

    assert wrapped(job) == "start:1:end"
    assert wrapped(job) == "start:2:end"


def test_exception_propagates() -> None:
    def job() -> str:
        raise ValueError("boom")

    with pytest.raises(ValueError, match="boom"):
        wrapped(job)


def test_helper_prints_nothing(capsys: pytest.CaptureFixture[str]) -> None:
    assert wrapped(lambda: "quiet") == "start:quiet:end"
    captured = capsys.readouterr()
    assert captured.out == ""
    assert captured.err == ""


def test_only_job_output_appears(capsys: pytest.CaptureFixture[str]) -> None:
    def job() -> str:
        print("from job")
        return "r"

    assert wrapped(job) == "start:r:end"
    captured = capsys.readouterr()
    assert captured.out == "from job\n"
    assert captured.err == ""


def test_helper_logs_nothing(caplog: pytest.LogCaptureFixture) -> None:
    with caplog.at_level(logging.DEBUG):
        assert wrapped(lambda: "r") == "start:r:end"
    assert caplog.records == []


def test_job_logging_is_the_only_logging(caplog: pytest.LogCaptureFixture) -> None:
    log = logging.getLogger("caller")

    def job() -> str:
        log.info("job ran")
        return "r"

    with caplog.at_level(logging.DEBUG):
        assert wrapped(job) == "start:r:end"
    assert [r.getMessage() for r in caplog.records] == ["job ran"]
